## Cache Miss-Storm: Dealing with Thundering Herd

## The Problem at Scale

```
Highly trafficked product page: 10,000 requests/second
Cache TTL: 60 seconds

At t=60s: cache expires
  → All 10,000 req/s simultaneously miss
  → 10,000 parallel DB queries for the same data
  → DB CPU spikes to 100%
  → Response time degrades for ALL requests
  → Potentially cascading failure
```

## Strategy 1: Distributed Lock (Cache Stampede Prevention)

```typescript
const LOCK_TTL = 10; // max seconds to hold the lock

async function getWithLock<T>(key: string, fetcher: () => Promise<T>): Promise<T> {
  // Fast path: cache hit
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);

  // Slow path: try to acquire lock
  const lockKey = `lock:${key}`;
  const lockId = crypto.randomUUID();
  const acquired = await redis.set(lockKey, lockId, { NX: true, EX: LOCK_TTL });

  if (acquired) {
    // This request won — fetch and populate cache
    try {
      const data = await fetcher();
      await redis.setEx(key, 3600, JSON.stringify(data));
      return data;
    } finally {
      // Only release if we still own the lock
      const current = await redis.get(lockKey);
      if (current === lockId) await redis.del(lockKey);
    }
  } else {
    // Lost the race — poll for the winner to populate cache
    for (let i = 0; i < 20; i++) {
      await sleep(100);
      const result = await redis.get(key);
      if (result) return JSON.parse(result);
    }
    // Fallback: fetch directly (lock timed out)
    return fetcher();
  }
}
```

## Strategy 2: Stale-While-Revalidate + Background Refresh

```typescript
interface CacheEntry<T> {
  data: T;
  expiresAt: number;  // when to start refreshing
  serveUntil: number; // when to refuse to serve stale data
}

async function getStaleWhileRevalidate<T>(
  key: string,
  fetcher: () => Promise<T>,
  ttl: number = 60,
  staleTtl: number = 120
): Promise<T> {
  const raw = await redis.get(key);

  if (raw) {
    const entry: CacheEntry<T> = JSON.parse(raw);
    const now = Date.now();

    if (now < entry.expiresAt) {
      return entry.data; // fresh — serve immediately
    }

    if (now < entry.serveUntil) {
      // Stale but within grace period
      // Trigger background refresh if no lock held
      const lockKey = `refresh:${key}`;
      const locked = await redis.set(lockKey, '1', { NX: true, EX: ttl });
      if (locked) {
        setImmediate(async () => {
          const fresh = await fetcher();
          const newEntry: CacheEntry<T> = {
            data: fresh,
            expiresAt: Date.now() + ttl * 1000,
            serveUntil: Date.now() + staleTtl * 1000,
          };
          await redis.setEx(key, staleTtl, JSON.stringify(newEntry));
        });
      }
      return entry.data; // serve stale immediately — no wait!
    }
  }

  // Cache miss or too stale — must fetch
  const data = await fetcher();
  const entry: CacheEntry<T> = {
    data,
    expiresAt: Date.now() + ttl * 1000,
    serveUntil: Date.now() + staleTtl * 1000,
  };
  await redis.setEx(key, staleTtl, JSON.stringify(entry));
  return data;
}
```

## Strategy 3: L1 (In-Process) + L2 (Redis)

```typescript
// In-process LRU cache as L1 — prevents Redis storms during refill
const l1 = new LRUCache<string, unknown>({ max: 500, ttl: 5_000 }); // 5s TTL

async function get<T>(key: string, fetcher: () => Promise<T>): Promise<T> {
  // L1: in-process (sub-ms)
  const l1hit = l1.get(key);
  if (l1hit) return l1hit as T;

  // L2: Redis
  const l2hit = await redis.get(key);
  if (l2hit) {
    const data = JSON.parse(l2hit) as T;
    l1.set(key, data); // populate L1
    return data;
  }

  // Miss: fetch and populate both levels
  const data = await getWithLock(key, fetcher);
  l1.set(key, data);
  return data;
}
// During cache refill: L1 serves thousands of requests per second
// with zero Redis calls, eliminating the stampede at the Redis level
```

